package cz.ioff.app;import android.service.notification.*;import android.content.*;import java.util.*;public class NotificationCaptureService extends NotificationListenerService{public void onNotificationPosted(StatusBarNotification s){if(s==null||s.getPackageName()==null)return;SharedPreferences p=getSharedPreferences("ioff",0);Set<String>d=new HashSet<>(Arrays.asList("com.instagram.android","com.facebook.katana","com.zhiliaoapp.musically","com.google.android.youtube","com.twitter.android","com.reddit.frontpage"));if(!p.getStringSet("blocked_apps",d).contains(s.getPackageName()))return;int day=p.getInt("focus_day",p.getInt("day",1));String k="exp_"+day+"_notifications";p.edit().putInt(k,p.getInt(k,0)+1).apply();}}
